breach.segment:
// SQL Server engine marker: excludes MySQL / PostgreSQL instances that share cpu metrics
WHERE ss > 0 AND cpu_n > 0
// Minimum samples: ~5 minutes of CPU data so a single late sample cannot trigger
| WHERE cpu_n >= 5
// Exact mean across fragments: SUM(SUM_OVER_TIME) / SUM(COUNT_OVER_TIME)
| EVAL cpu_avg_pct = ROUND(cpu_sum / cpu_n * 100.0, 1),
       cpu_peak_pct = ROUND(cpu_peak * 100.0, 1),
       rq_avg = ROUND(rq_avg, 2)
// Alert thresholds:
//  - average CPU utilization (percent of reserved vCPUs) over the rule window
//  - average runnable tasks (queries waiting for a CPU). Remove this line to alert on
//    CPU utilization alone; raise it (e.g. to the vCPU count) for large instances.
| WHERE cpu_avg_pct >= 90
| WHERE rq_avg >= 1
| KEEP database_id, cpu_avg_pct, cpu_peak_pct, rq_avg, rq_peak, cores
| SORT cpu_avg_pct DESC
| LIMIT 100
